// 统一告警格式化 (支持 Zabbix/Prometheus/自定义)
const input = $input.first().json;
const cstTime = new Date().toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' });

// 统一解析不同来源的告警
let alert = {
  source: 'unknown',
  level: 'warning',
  title: '',
  message: '',
  host: '',
  metric: '',
  value: '',
  timestamp: cstTime,
};

// Zabbix 格式
if (input.host || input.trigger) {
  alert.source = 'zabbix';
  alert.level = input.severity || input.priority || 'warning';
  alert.title = input.trigger || input.subject || '未知告警';
  alert.message = input.message || input.description || '';
  alert.host = input.host || input.hostname || '';
}
// Prometheus/Alertmanager 格式
else if (input.alerts || input.commonLabels) {
  const a = (input.alerts || [{}])[0];
  alert.source = 'prometheus';
  alert.level = a.labels?.severity || input.commonLabels?.severity || 'warning';
  alert.title = a.labels?.alertname || input.commonLabels?.alertname || '未知告警';
  alert.message = a.annotations?.description || a.annotations?.summary || '';
  alert.host = a.labels?.instance || '';
}
// 自定义格式
else {
  alert.source = input.source || 'custom';
  alert.level = input.level || input.severity || 'warning';
  alert.title = input.title || input.alert_name || '未知告警';
  alert.message = input.message || input.description || JSON.stringify(input).slice(0, 500);
  alert.host = input.host || input.target || '';
}

// 判断是否需要 AI 诊断
const needDiagnosis = ['critical', 'error', 'high', '3', '4', '5'].includes(String(alert.level).toLowerCase());
alert.need_diagnosis = needDiagnosis;

return alert;

// Z-OPS n8n_callback HMAC 签名 (task-c17; secret=zops.env N8N_CALLBACK_SECRET)
const crypto = require('crypto');
const secret = process.env.ZOPS_N8N_CALLBACK_SECRET || '<部署时填 zops.env 的 N8N_CALLBACK_SECRET>';
const body = JSON.stringify($input.first().json);  // 与 httpRequest raw body 完全一致
const ts = String(Math.floor(Date.now()/1000));
const nonce = crypto.randomBytes(8).toString('hex');
const payload = ['POST','/api/webhook/n8n_callback',body,ts,nonce].join('\n');
return [{ json: { __body: body, __sig: crypto.createHmac('sha256', secret).update(payload).digest('hex'), __ts: ts, __nonce: nonce } }];
